public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the message is empty
    if (message.isEmpty()) {
        return false;
    }

    // Check if the timestamp is valid
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp must be a positive integer");
    }

    // Check if the message is within the allowed time range
    if (timestamp < 10 || timestamp > 60) {
        return false;
    }

    // Check if the message is a valid string
    if (!message.matches("[a-zA-Z0-9 ]+")) {
        throw new IllegalArgumentException("Message must be a string of letters, digits, or spaces");
    }

    // Check if the message is within the allowed length range
    if (message.length() < 5 || message.length() > 10) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

