        for (int i = 0; i < argTypes.length; i++) {
            final String argType = argTypes[i];
            if (argType.equals("J") || argType.equals("D")) {
                // Long or double
                popLong();
            } else {
                // All other types
                pop();
            }
        }
    } else {
        // Type descriptor
        if (descriptor.equals("J") || descriptor.equals("D")) {
            // Long or double
            popLong();
        } else {
            // All other types
            pop();
        }
    }
}

