        // If there are no vertices left, return null
        return null;
    }

    // Get the next vertex to visit
    V nextVertex = vertices.remove(0);

    // Check if the vertex has already been visited
    if (visited.contains(nextVertex)) {
        // If the vertex has already been visited, return the next vertex
        return provideNextVertex();
    }

    // Mark the vertex as visited
    visited.add(nextVertex);

    // Return the next vertex
    return nextVertex;
}

