public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the row is within the bounds of the table
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    // Select the row in the table
    table.setRowSelectionInterval(row, row);

    // Scroll the pane to the selected row
    pane.getVerticalScrollBar().setValue(pane.getVerticalScrollBar().getMaximum());

    // Repaint the table to ensure the newly selected row is properly painted
    table.repaint();
}

