    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }
    if (buf == null) {
        throw new NullPointerException("Null buffer");
    }

    int i = nameStart;
    while (i < buf.length() && buf.charAt(i) != ' ') {
        i++;
