public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day of the week from the time bucket
    int dayOfWeek = (int) (timeBucket % 100000000);

    // Calculate the new day of the week based on the day step
    dayOfWeek = dayOfWeek + dayStep;

    // If the new day of the week is greater than 7, subtract 7 to get the correct day of the week
    if (dayOfWeek > 7) {
        dayOfWeek = dayOfWeek - 7;
    }

    // Calculate the new time bucket by replacing the day of the week with the new day of the week
    long newTimeBucket = timeBucket - (timeBucket % 100000000) + dayOfWeek;

    return newTimeBucket;
}

