public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            char d = str.charAt(i);
            if (Character.isLowSurrogate(d)) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid low surrogate");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

